import Index from "views/Index.js";
import Profile from "views/examples/Profile.js";
import Register from "views/examples/Register.js";
import Login from "views/examples/Login.js";
import Tables from "views/examples/Tables.js";

// Define ALL routes, including Login and Register
const allRoutes = [
  {
    path: "/index",
    name: "EcoCred",
    icon: "ni ni-tv-2 text-primary",
    component: <Index />,
    layout: "/admin",
  },
  {
    path: "/tables",
    name: "Carbon Actions Log",
    icon: "ni ni-bullet-list-67 text-red",
    component: <Tables />,
    layout: "/admin",
  },
  {
    path: "/login",
    name: "Login",
    component: <Login />, // No icon or layout for sidebar
    layout: "/auth",
  },
  {
    path: "/register",
    name: "Register",
    component: <Register />, // No icon or layout for sidebar
    layout: "/auth",
  },
  {
    path: "/user-profile",
    name: "User Profile",
    icon: "ni ni-single-02 text-yellow",
    component: <Profile />,
    layout: "/admin",
  },
];

// Define routes ONLY for the sidebar navigation
const sidebarRoutes = [
  {
    path: "/index",
    name: "EcoCred",
    icon: "ni ni-tv-2 text-primary",
    component: <Index />,
    layout: "/admin",
  },
  {
    path: "/tables",
    name: "Carbon Actions Log",
    icon: "ni ni-bullet-list-67 text-red",
    component: <Tables />,
    layout: "/admin",
  },
  {
    path: "/user-profile",
    name: "User Profile",
    icon: "ni ni-single-02 text-yellow",
    component: <Profile />,
    layout: "/admin",
  },
];


export { allRoutes, sidebarRoutes }; // Export both route arrays
